export function requireAbsolutePath(value: unknown, field: string): string {
  const path = requireString(value, field, { minLength: 1, maxLength: LIMITS.maxPathChars })
  if (path.includes('\u0000')) throw new ValidationError(`${field} must not contain a NUL byte`, field)
  const absolute = path.startsWith('/') || /^[A-Za-z]:[\\/]/.test(path) || path.startsWith('\\\\')
  if (!absolute) throw new ValidationError(`${field} must be an absolute path`, field)
  if (hasParentSegment(path)) throw new ValidationError(`${field} must not contain a parent segment`, field)
  return path
}
